{
  "name": "builder_gap_threshold_001",
  "intuition": "Filter out near-ties by requiring a minimum objective gap; this reduces noisy/ambiguous preferences and emphasizes clearer signal while keeping all qualifying pairs.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Keep only pairs with a meaningful objective gap to avoid noisy near-ties.\n    gap_threshold = extra.get('gap_threshold', 0.0)\n    gap = objective[:, :, None] - objective[:, None, :]\n    mask = gap < (-gap_threshold)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'gap_threshold', 'gap_threshold': float(gap_threshold)})\n"
}

{
  "name": "builder_gap_threshold_001",
  "intuition": "Filter out near-ties by requiring a minimum objective gap between winner and loser; this reduces noisy/ambiguous preferences and improves training signal quality while keeping clear pairwise supervision.",
