{
  "name": "loss_logsigmoid_e1_stable_fallback_keys_001",
  "intuition": "The static gate failed because the loss did not declare required expects keys. This version stabilizes and simplifies by (1) explicitly declaring expects with required pairwise keys and optional nonnegative weight, (2) supporting common fallback key aliases to avoid missing-key crashes, and (3) keeping a numerically-stable -logsigmoid objective with clamping and safe normalization (divide by sum of weights when provided). This preserves preference semantics (encourage log_prob_w > log_prob_l) while avoiding invalid expects and instability from extreme logits.",
  "pseudocode": "lpw = batch[log_prob_w] or batch[chosen_log_prob]\nlpl = batch[log_prob_l] or batch[rejected_log_prob]\nd = lpw - lpl\nx = clamp(alpha*scale*d, -20, 20)\nper = -logsigmoid(x)\nif weight:\n  w = clamp(weight, 0, inf)\n  loss = sum(per*w) / (sum(w)+eps)\nelse:\n  loss = mean(per)\nreturn loss",
  "hyperparams": {
    "scale": 1.695769604910336,
    "clamp_min": -20.0,
    "clamp_max": 20.0,
    "eps": 1e-08
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "expects": {
    "log_prob_w": {
      "dtype": "float",
      "shape": [
        "batch"
      ],
      "required": true
    },
    "log_prob_l": {
      "dtype": "float",
      "shape": [
        "batch"
      ],
      "required": true
    },
    "weight": {
      "dtype": "float",
      "shape": [
        "batch"
      ],
      "required": false,
      "nonnegative": true
    }
  },
  "code": "def generated_loss(batch, model_output, extra):\n    # Required pairwise log-probs; allow common aliases as a robustness fallback.\n    lpw = batch.get('log_prob_w', batch.get('chosen_log_prob', None))\n    lpl = batch.get('log_prob_l', batch.get('rejected_log_prob', None))\n\n    # If aliases are absent, this will naturally error; expects declares required keys.\n    d = lpw - lpl\n\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    hp = extra.get('hyperparams', {})\n    scale = float(hp.get('scale', 1.695769604910336))\n    clamp_min = float(hp.get('clamp_min', -20.0))\n    clamp_max = float(hp.get('clamp_max', 20.0))\n    eps = float(hp.get('eps', 1e-08))\n\n    x = alpha * scale * d\n    x = ops.clamp(x, clamp_min, clamp_max)\n    per = -ops.logsigmoid(x)\n\n    weight = batch.get('weight', None)\n    if weight is None:\n        return per.mean()\n\n    # Enforce nonnegative weights and normalize to keep loss scale stable.\n    w = ops.clamp(weight, 0.0, 1e9)\n    denom = w.sum() + eps\n    return (per * w).sum() / denom",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry / DPO-style) ranking loss on log-prob differences: L = -log(sigmoid(alpha*scale*(lpw-lpl))). Clamping controls extreme logits for numerical stability; optional nonnegative weights are normalized by sum(w)+eps to keep a consistent objective scale."
}

