{
  "name": "loss_logsigmoid_consensus_huber_000",
  "intuition": "All parents share a stable core: a pairwise preference objective using -logsigmoid on the log-prob margin (log_prob_w - log_prob_l), with clamping for numerical stability and optional per-example weighting. A safe consensus refinement is to keep the same monotone objective but add a small, vectorized Huber-style penalty on the margin to discourage extreme margins and stabilize gradients without changing the optimum ordering; this preserves the robust pairwise learning signal while reducing sensitivity to outliers.",
  "pseudocode": "m = alpha*scale*(lpw-lpl); m = clamp(m, -clamp_val, clamp_val); base = -logsigmoid(m); huber = where(|m|<=delta, 0.5*(m/delta)^2, |m|/delta - 0.5); loss = base + reg_weight*huber; if weight: loss*=weight; mean(loss)",
  "hyperparams": {
    "scale": 1.35,
    "clamp_val": 20.0,
    "delta": 6.0,
    "reg_weight": 0.02
  },
  "operators_used": [
    "logsigmoid",
    "clamp",
    "abs",
    "where"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    hp = extra.get('hyperparams', {})\n    scale = float(hp.get('scale', 1.35))\n    clamp_val = float(hp.get('clamp_val', 20.0))\n    delta = float(hp.get('delta', 6.0))\n    reg_weight = float(hp.get('reg_weight', 0.02))\n\n    m = alpha * scale * (lpw - lpl)\n    m = ops.clamp(m, -clamp_val, clamp_val)\n\n    base = -ops.logsigmoid(m)\n\n    # Smooth L1 (Huber) penalty on the margin to dampen extreme margins.\n    abs_m = ops.abs(m)\n    d = ops.clamp(ops.tensor(delta, device=m.device, dtype=m.dtype), 1e-6, 1e6)\n    quad = 0.5 * (abs_m / d) * (abs_m / d)\n    lin = (abs_m / d) - 0.5\n    huber = ops.where(abs_m <= d, quad, lin)\n\n    loss = base + reg_weight * huber\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) preference loss on log-prob margins encourages P(w) > P(l). Clamping prevents numerical overflow. Adding a small Huber-style penalty on the margin regularizes overly large margins, improving stability under heavy-tailed log-prob differences while keeping the learning signal monotone in the margin.",
  "implementation_hint": {
    "expects": {
      "batch": ["log_prob_w", "log_prob_l"],
      "batch_optional": ["weight"],
      "model_output": [],
      "extra": ["hyperparams", "alpha"]
    },
    "notes": "Vectorized over the batch. Returns a scalar mean loss. Uses only ops.* tensor operations; no Python loops."
  }
}

